const std = @import("std");
const tensor = @import("../tensor/tensor.zig");
const linear_mod = @import("../nn/linear.zig");
const config = @import("../util/config.zig");

pub const EFLAHead = struct {
    state: []f32,
    state_dim: u32,
    value_dim: u32,
    beta: f32,
    beta_param: ?tensor.Tensor,
    beta_learnable: bool,
    lambda_threshold: f64,
    series_terms: u32,

    pub fn init(allocator: std.mem.Allocator, state_dim: u32, value_dim: u32, cfg: config.EflaConfig) !EFLAHead {
        // JAVÍTÁS: Integer overflow elkerülése usize-használattal
        const state_size = @as(usize, state_dim) * @as(usize, value_dim);
        const state = try allocator.alloc(f32, state_size);

        // JAVÍTÁS: Memóriaszivárgás elkerülése hiba esetén (errdefer)
        errdefer allocator.free(state);

        @memset(state, 0);

        var beta_param: ?tensor.Tensor = null;
        if (cfg.beta_learnable) {
            const beta_shape = tensor.Shape.init(&[_]u64{1});
            var bp = try tensor.zeros(allocator, beta_shape, .fp32);

            // JAVÍTÁS: Ha a tensor inicializálása sikertelen, a state nem szivárog ki (már van errdefer)
            errdefer bp.deinit();

            bp.requires_grad = true;
            bp.setName("efla.beta");
            bp.dataAsF32()[0] = cfg.beta_init;
            beta_param = bp;
        }

        return .{
            .state = state,
            .state_dim = state_dim,
            .value_dim = value_dim,
            .beta = cfg.beta_init,
            .beta_param = beta_param,
            .beta_learnable = cfg.beta_learnable,
            .lambda_threshold = cfg.lambda_threshold,
            .series_terms = cfg.series_terms,
        };
    }

    pub fn deinit(self: *EFLAHead, allocator: std.mem.Allocator) void {
        allocator.free(self.state);
        if (self.beta_param) |*bp| {
            bp.deinit();
        }
    }

    pub fn resetState(self: *EFLAHead) void {
        @memset(self.state, 0);
    }

    pub fn getCurrentBeta(self: *const EFLAHead) f32 {
        if (self.beta_param) |bp| {
            return bp.dataAsF32()[0];
        }
        return self.beta;
    }

    fn computeCoefficient(self: *const EFLAHead, lambda: f64, beta_val: f64) f64 {
        // JAVÍTÁS: Nullával való osztás kezelése
        if (lambda < self.lambda_threshold or lambda == 0.0) {
            // JAVÍTÁS: series_terms logikájának helyes implementálása
            // Taylor sor: beta - (beta^2 * lambda)/2 + (beta^3 * lambda^2)/6 - ...

            const b2 = beta_val * beta_val;
            const b3 = b2 * beta_val;
            const l2 = lambda * lambda;

            // 0. és 1. tag (series_terms >= 1 implicit a feltételben, de a 2. taghez series_terms >= 2 kell)
            // A specifikáció szerint a 2. tag (lineáris tag) hozzáadása feltételes.
            // Feltételezzük, hogy series_terms = 1 -> csak beta. series_terms = 2 -> beta - 0.5*b^2*l.

            var c: f64 = beta_val;

            if (self.series_terms >= 2) {
                c += -0.5 * b2 * lambda;
            }
            if (self.series_terms >= 3) {
                c += b3 * l2 / 6.0;
            }
            if (self.series_terms >= 4) {
                const b4 = b3 * beta_val;
                const l3 = l2 * lambda;
                c += -b4 * l3 / 24.0;
            }
            // JAVÍTÁS: 4-nél nagyobb term-ek kezelése (kiterjesztés vagy levágás)
            // Itt levágjuk a sort, de a struktúra lehetővé teszi kiterjesztést.
            return c;
        }

        return (1.0 - @exp(-beta_val * lambda)) / lambda;
    }

    pub fn step(self: *EFLAHead, k: []const f32, v: []const f32, output: []f32) void {
        const d = self.state_dim;
        const dv = self.value_dim;

        // JAVÍTÁS: Biztonságos castolás és típusok
        const d_usize = @as(usize, d);
        const dv_usize = @as(usize, dv);

        std.debug.assert(k.len >= d_usize);
        std.debug.assert(v.len >= dv_usize);
        std.debug.assert(output.len >= dv_usize);

        const beta_val: f64 = @as(f64, self.getCurrentBeta());

        var lambda: f64 = 0;
        // JAVÍTÁS: usize indexek
        for (k[0..d_usize]) |ki| {
            lambda += @as(f64, ki) * @as(f64, ki);
        }

        const c = self.computeCoefficient(lambda, beta_val);
        const c_f32: f32 = @floatCast(c);

        // JAVÍTÁS: Cache-lokalitás javítása (i a külső, j a belső ciklus)
        // Ezzel elkerüljük a state ugrálását a memóriában.

        // 1. Kiszámoljuk az output vektort (z = k^T * State) a frissítés előtt.
        // Ez javítja a szemantikai hibát (output a régi állapot alapján készül).
        // Inicializáljuk az outputot 0-val.
        @memset(output[0..dv_usize], 0);

        for (0..d_usize) |i| {
            const ki = k[i];
            if (ki == 0) continue; // Optimalizáció
            const state_row = self.state[i * dv_usize .. (i + 1) * dv_usize];
            for (0..dv_usize) |j| {
                output[j] += ki * state_row[j];
            }
        }

        // 2. Frissítjük az állapotot: State = State + c * k * (v - output)
        // output jelenleg a z = k^T * State.
        // A képlet: State = State - c * k * z + c * k * v
        //          = State + c * k * (v - z)

        for (0..d_usize) |i| {
            const ki = k[i];
            if (ki == 0) continue;

            const coeff = c_f32 * ki;
            const state_row = self.state[i * dv_usize .. (i + 1) * dv_usize];

            for (0..dv_usize) |j| {
                const val = v[j]; // v[j] biztonságos, lásd fent
                const out = output[j]; // ez a z
                state_row[j] += coeff * (val - out);
            }
        }

        // JAVÍTÁS: A duplikált logikai blokk és a halott kód (ckv) eltávolítva.
        // Az output már ki van számolva a helyes (pre-update) állapotból.
    }

    pub fn forwardSequence(self: *EFLAHead, keys: []const f32, values: []const f32, output: []f32, seq_len: u32) void {
        const d = self.state_dim;
        const dv = self.value_dim;
        const seq_len_usize = @as(usize, seq_len);
        const d_usize = @as(usize, d);
        const dv_usize = @as(usize, dv);

        for (0..seq_len_usize) |t| {
            // JAVÍTÁS: usize aritmetika a túlcsordulás elkerülésére
            const k_offset = t * d_usize;
            const v_offset = t * dv_usize;
            const o_offset = t * dv_usize;

            self.step(
                keys[k_offset .. k_offset + d_usize],
                values[v_offset .. v_offset + dv_usize],
                output[o_offset .. o_offset + dv_usize],
            );
        }
    }
};

pub const EFLALayer = struct {
    // JAVÍTÁS: q_proj eltávolítva (halott kód/architekturális hiba)
    k_proj: linear_mod.Linear,
    v_proj: linear_mod.Linear,
    o_proj: linear_mod.Linear,
    heads: []EFLAHead,
    num_heads: u32,
    state_dim: u32,
    value_dim: u32,
    hidden_dim: u32,
    // chunk_size eltávolítva (halott mező)
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, hidden_dim: u32, cfg: config.EflaConfig, seed: u64) !EFLALayer {
        const total_kv_dim = cfg.num_heads * cfg.state_dim;
        const total_v_dim = cfg.num_heads * cfg.value_dim;

        // JAVÍTÁS: Errdefer használata a memóriaszivárgás elkerülésére
        var k_proj = try linear_mod.Linear.init(allocator, hidden_dim, total_kv_dim, false, seed +% 1);
        errdefer k_proj.deinit();

        var v_proj = try linear_mod.Linear.init(allocator, hidden_dim, total_v_dim, false, seed +% 2);
        errdefer v_proj.deinit();

        var o_proj = try linear_mod.Linear.init(allocator, total_v_dim, hidden_dim, false, seed +% 3);
        errdefer o_proj.deinit();

        k_proj.weight.setName("efla.k_proj");
        v_proj.weight.setName("efla.v_proj");
        o_proj.weight.setName("efla.o_proj");

        const heads = try allocator.alloc(EFLAHead, cfg.num_heads);
        errdefer allocator.free(heads);

        // JAVÍTÁS: Részleges inicializáció kezelése
        var initialized_count: usize = 0;
        errdefer {
            for (heads[0..initialized_count]) |*h| {
                h.deinit(allocator);
            }
        }

        for (heads) |*h| {
            h.* = try EFLAHead.init(allocator, cfg.state_dim, cfg.value_dim, cfg);
            initialized_count += 1;
        }

        return .{
            .k_proj = k_proj,
            .v_proj = v_proj,
            .o_proj = o_proj,
            .heads = heads,
            .num_heads = cfg.num_heads,
            .state_dim = cfg.state_dim,
            .value_dim = cfg.value_dim,
            .hidden_dim = hidden_dim,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EFLALayer) void {
        self.k_proj.deinit();
        self.v_proj.deinit();
        self.o_proj.deinit();
        for (self.heads) |*h| {
            h.deinit(self.allocator);
        }
        self.allocator.free(self.heads);
    }

    pub fn resetState(self: *EFLALayer) void {
        for (self.heads) |*h| {
            h.resetState();
        }
    }

    pub fn forward(self: *EFLALayer, input: []const f32, output: []f32, seq_len: u32) !void {
        const total_k_dim = self.num_heads * self.state_dim;
        const total_v_dim = self.num_heads * self.value_dim;

        const seq_len_z = @as(usize, seq_len);
        const total_k_dim_z = @as(usize, total_k_dim);
        const total_v_dim_z = @as(usize, total_v_dim);

        // JAVÍTÁS: Allokációk a függvény elején, cikluson kívül (Heap churn fix)
        const keys = try self.allocator.alloc(f32, seq_len_z * total_k_dim_z);
        defer self.allocator.free(keys);
        const values = try self.allocator.alloc(f32, seq_len_z * total_v_dim_z);
        defer self.allocator.free(values);

        // Output buffer a fejek kimenetének összefűzésére
        const head_output = try self.allocator.alloc(f32, seq_len_z * total_v_dim_z);
        defer self.allocator.free(head_output);

        self.k_proj.forward(input, keys, seq_len);
        self.v_proj.forward(input, values, seq_len);

        const sd = @as(usize, self.state_dim);
        const vd = @as(usize, self.value_dim);

        // JAVÍTÁS: Fejenkénti feldolgozás cikluson kívüli allokációval
        for (self.heads, 0..) |*h, idx| {
            const h_usize = @as(usize, idx);

            // Iterálunk az idő felett, és közvetlenül slice-olunk a nagy bufferből
            // Ez elkerüli a felesleges másolást és allokációt.
            for (0..seq_len_z) |t| {
                const k_start = t * total_k_dim_z + h_usize * sd;
                const v_start = t * total_v_dim_z + h_usize * vd;
                const o_start = t * total_v_dim_z + h_usize * vd;

                h.step(
                    keys[k_start .. k_start + sd],
                    values[v_start .. v_start + vd],
                    head_output[o_start .. o_start + vd],
                );
            }
        }

        self.o_proj.forward(head_output, output, seq_len);
    }

    pub fn paramCount(self: *const EFLALayer) u64 {
        var count: u64 = 0;
        count += self.k_proj.paramCount();
        count += self.v_proj.paramCount();
        count += self.o_proj.paramCount();
        // JAVÍTÁS: q_proj eltávolítva a számításból

        if (self.heads.len > 0 and self.heads[0].beta_learnable) {
            // JAVÍTÁS: Típuskonverzió u32 -> u64
            count += @as(u64, self.num_heads);
        }
        return count;
    }
};

test "efla head step" {
    const cfg = config.EflaConfig{
        .num_heads = 1,
        .state_dim = 4,
        .value_dim = 4,
        .beta_init = 0.1,
        .beta_learnable = false,
        .chunk_size = 512, // config mező, bár a layer nem használja
        .lambda_threshold = 1e-6,
        .series_terms = 4,
    };

    var head = try EFLAHead.init(std.testing.allocator, 4, 4, cfg);
    defer head.deinit(std.testing.allocator);

    const k = [_]f32{ 1.0, 0.0, 0.0, 0.0 };
    const v = [_]f32{ 1.0, 2.0, 3.0, 4.0 };
    var output: [4]f32 = undefined;

    // Első lépés: állapot frissítése, output 0 (mert state 0 volt)
    head.step(&k, &v, &output);

    // Ellenőrizzük, hogy az output valóban 0 (pre-update logika)
    for (output) |o| {
        try std.testing.expectEqual(@as(f32, 0.0), o);
    }

    // Második lépés: most már van állapot
    head.step(&k, &v, &output);

    // Ekkor az outputnak nem szabad nullának lennie.
    var has_nonzero = false;
    for (output) |o| {
        if (@abs(o) > 1e-10) has_nonzero = true;
    }
    try std.testing.expect(has_nonzero);
}

test "efla coefficient stability" {
    const cfg = config.EflaConfig{
        .num_heads = 1,
        .state_dim = 4,
        .value_dim = 4,
        .beta_init = 0.1,
        .beta_learnable = false,
        .chunk_size = 512,
        .lambda_threshold = 1e-6,
        .series_terms = 4,
    };

    var head = try EFLAHead.init(std.testing.allocator, 4, 4, cfg);
    defer head.deinit(std.testing.allocator);

    const c_small = head.computeCoefficient(1e-10, 0.1);
    try std.testing.expect(@abs(c_small - 0.1) < 0.01);

    const c_normal = head.computeCoefficient(1.0, 0.1);
    try std.testing.expect(c_normal > 0 and c_normal < 0.2);
}

